Text_24A4:
.stringn "\x05FL|CHINON||\x0701\x081Dそんなんで\x02w2オレを縛ろうとすんな。\x02w5\n"
.stringn "\x02mc………\x02md\x02w4\x02ecまぁ、\x02w3どうしてもってんなら\x02w3\n"
.stringn "考えてやらなくもないけどよぉ。\x02eo\x02w2\x11"
db 0
.align 4
//MMY_CHINON_RECV_0_A

